window.AUTH=window.AUTH||{};window.AUTH["21-1436"]={"d":"21-1436","id":"2022/21-1436","n":"Santos-Zacaria v. Garland","briefs":[{"k":"petitioner","label":"Brief of petitioner Leon Santos-Zacaria","date":"2022-11-17","url":"https://www.supremecourt.gov/DocketPDF/21/21-1436/246866/20221117171718532_21-1436.Petitioners%20Brief.pdf","side":"pet","n":92},{"k":"respondent","label":"Brief of respondent Merrick B. Garland, Attorney General","date":"2022-12-19","url":"https://www.supremecourt.gov/DocketPDF/21/21-1436/250395/20221219190937345_21-1436bsUnitedStates.pdf","side":"res","n":134},{"k":"reply","label":"Reply of petitioner Leon Santos-Zacaria","date":"2023-01-05","url":"https://www.supremecourt.gov/DocketPDF/21/21-1436/251486/20230105145928723_21-1436.reply.pdf","side":"pet","n":58}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r19_dc8f.pdf","tr":true,"items":[{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"by":{"0":"16, 17, 18, 19, 20, 32","1":"11, 14","2":"2, 8, 9"},"q":[{"src":"brief","b":0,"text":"does not speak in jurisdictional terms or refer in any way to the jurisdiction","cite":"546 U.S. at 515"},{"src":"argument","who":"Mr. Hughes","text":"I don't think that it's necessarily the case, if a court did something that I think Arbaugh calls a drive-by after --"},{"src":"argument","who":"Justice Kavanaugh","text":"And -- and in Nken, we repeated that post -- you know, post the -- the new act and post-Arbaugh, right?"},{"src":"argument","who":"Justice Kavanaugh","text":"And then -- but would there be systemic harm that the government's aware of from us saying, you know, an exhaustion requirement's -- in this Arbaugh world, an exhaustion requirement subcategory is only going to be jurisdictional if the word \"jurisdiction\" is used?"}]},{"t":"case","label":"Austin v. United States","cite":"513 U.S. 5","y":1994,"id":"scdb/1994-002","sc":1,"by":{"0":"36"}},{"t":"case","label":"Badgerow v. Walters","cite":"142 S. Ct. 1310","y":2022,"id":"2021/20-1143","sc":1,"by":{"0":"26, 41","2":"5"},"q":[{"src":"brief","b":0,"text":"generally take[s] [such a] choice to be deliberate.","cite":"142 S. Ct. 1310, 1318"}]},{"t":"case","label":"Biden v. Texas","cite":"142 S. Ct. 2528","y":2022,"id":"2021/21-954","sc":1,"by":{"0":"19, 24, 26, 42","1":"18, 23","2":"2, 4"},"q":[{"src":"brief","b":0,"text":"no court shall have jurisdiction to review.","cite":"142 S. Ct. at 2539"},{"src":"brief","b":0,"text":"it could have said so in words far simpler than those that it wrote.","cite":"142 S. Ct. at 2539"}]},{"t":"case","label":"Boechler, P.C. v. Commissioner of Internal Revenue","cite":"142 S. Ct. 1493","y":2022,"id":"2021/20-1472","sc":1,"by":{"0":"3, 13, 16, 17, 18, 21, 29","1":"11, 14, 23","2":"1, 5, 10, 11, 18"},"q":[{"src":"brief","b":0,"text":"only if Congress ‘clearly states’ that it is.","cite":"142 S. Ct. at 1497"},{"src":"brief","b":0,"text":"[t]o satisfy the clear-statement rule, the jurisdictional condition must be just that: clear.","cite":"142 S. Ct. at 1499"},{"src":"brief","b":1,"text":"mark[s] the bounds of a ‘court’s adjudicatory authority,’","cite":"142 S. Ct. 1493, 1497"},{"src":"brief","b":2,"text":"[t]he only jurisdictional language appears in the parenthetical at the end of the sentence.","cite":"142 S. Ct. at 1497"},{"src":"brief","b":2,"text":"parsed a single statutory sentence to distinguish between its jurisdictional and nonjurisdictional elements.","cite":"142 S. Ct. at 1499"},{"src":"argument","who":"Mr. Hughes","text":"The Court was quite clear in Boechler saying that's not the test. It's the government has to show their interpretation as jurisdictional is the only plausible argument for them to demonstrate that."}]},{"t":"case","label":"Bolin v. Sears, Roebuck & Co.","cite":"231 F.3d 970","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/231/970/","by":{"0":"23"}},{"t":"case","label":"Brotherhood of R.R. Trainmen v. Baltimore & O.R. Co.","cite":"331 U.S. 519","y":1947,"id":"scdb/1946-111","sc":1,"by":{"0":"36, 38"}},{"t":"case","label":"Carr v. Saul","cite":"141 S. Ct. 1352","y":2021,"id":"2020/19-1442","sc":1,"by":{"0":"30, 32","1":"29, 30, 34","2":"13, 15, 16, 17, 18"},"q":[{"src":"brief","b":0,"text":"[i]ssue exhaustion should not be confused with exhaustion of administrative remedies.","cite":"141 S. Ct. 1352, 1358 n.2"},{"src":"brief","b":0,"text":"whether to require issue exhaustion based on ‘an analogy to the rule that appellate courts will not consider arguments not raised before trial courts.’","cite":"141 S. Ct. at 1358"},{"src":"brief","b":1,"text":"claimants bear the responsibility to develop issues for adjudicators’ consideration,","cite":"141 S. Ct. 1352, 1358"},{"src":"brief","b":1,"text":"[i]ssue exhaustion should not be confused with exhaustion of administrative remedies.","cite":"141 S. Ct. at 1358 n.2"},{"src":"argument","who":"Mr. Hughes","text":"And I think that's a -- a completely separate and independent concern with the government's position because, again, issue preservation, as this Court in -- in Carr and Sims and a series of cases has said, is a doctrine that is distinct from remedy exhaustion."}]},{"t":"case","label":"Castro v. United States","cite":"540 U.S. 375","y":2003,"id":"2003/02-6683","sc":1,"by":{"0":"33"},"q":[{"src":"brief","b":0,"text":"parties know what is best for them.","cite":"540 U.S. 375, 386"}]},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"by":{"0":"39"},"q":[{"src":"brief","b":0,"text":"[a] statute should be construed so that effect is given to all its provisions, so that no part will be inoperative or superfluous, void or insignificant.’","cite":"556 U.S. 303, 314"}]},{"t":"case","label":"EPA v. EME Homer City Generation","cite":"572 U.S. 489","y":2014,"id":"2013/12-1182","sc":1,"by":{"0":"19, 26","2":"6, 11"},"q":[{"src":"brief","b":0,"text":"speak[s] to * * * a party’s procedural obligations,","cite":"572 U.S. 489, 512"},{"src":"brief","b":2,"text":"speak[s] to * * * a party’s pro- cedural obligations.","cite":"572 U.S. at 512"}]},{"t":"case","label":"FCC v. AT&T, Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"by":{"0":"39"}},{"t":"case","label":"Flores-Flores v. Garland","cite":"2022 WL 3031314","y":2022,"court":"5th Cir.","by":{"0":"34, 45"}},{"t":"case","label":"Fort Bend Cnty. v. Davis","cite":"139 S. Ct. 1843","y":2019,"id":"2018/18-525","sc":1,"by":{"0":"17, 20, 21, 22, 26","1":"15","2":"2, 6, 9"},"q":[{"src":"brief","b":0,"text":"delineat[es] the classes of cases a court may entertain,","cite":"139 S. Ct. at 1848"},{"src":"brief","b":0,"text":"courts should treat the restriction as nonjurisdictional in character.","cite":"139 S. Ct. at 1850"},{"src":"brief","b":1,"text":"the classes of cases a court may entertain.","cite":"139 S. Ct. 1843, 1846"},{"src":"brief","b":2,"text":"classes of cases a court may entertain","cite":"139 S. Ct. at 1848"},{"src":"argument","who":"Justice Kavanaugh","text":"And so I -- I guess I'm still -- put aside the example you gave -- why shouldn't the divide -- and we referred in Fort Bend to the divide being does the provision speak to a court's authority as opposed to a party's procedural obligations, and this seems to speak to the court's authority because it says a court may review only if."},{"src":"argument","who":"Justice Kavanaugh","text":"And why -- why then do we have a special magic words requirement just for exhaustion requirements and not just follow the usual Fort Bend divide?"}]},{"t":"case","label":"FPC v. Colorado Interstate Gas Co.","cite":"348 U.S. 492","y":1955,"id":"scdb/1954-047","sc":1,"by":{"0":"30","1":"25"}},{"t":"case","label":"George v. McDonough","cite":"142 S. Ct. 1953","y":2022,"id":"2021/21-234","sc":1,"by":{"0":"39"}},{"t":"case","label":"Greenlaw v. United States","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"by":{"0":"33"},"q":[{"src":"brief","b":0,"text":"[Courts] do not, or should not, sally forth each day looking for wrongs to right.","cite":"554 U.S. 237, 244"},{"src":"brief","b":0,"text":"the richest, most powerful, and best represented litigant","cite":"554 U.S. at 244"}]},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"140 S. Ct. 1062","y":2020,"id":"2019/18-776","sc":1,"by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"can only be overcome by ‘clear and convincing evidence’ of congressional intent to preclude judicial review.","cite":"140 S. Ct. 1062, 1069"}]},{"t":"case","label":"Halbert v. Michigan","cite":"545 U.S. 605","y":2005,"id":"2004/03-10198","sc":1,"by":{"0":"36"},"q":[{"src":"brief","b":0,"text":"a State need not appoint counsel to aid a poor person in discretionary appeals.","cite":"545 U.S. 605, 610"}]},{"t":"case","label":"Hamer v. Neighborhood Hous. Servs. of Chi.","cite":"138 S. Ct. 13","y":2017,"id":"2017/16-658","sc":1,"by":{"0":"17, 28","2":"16"},"q":[{"src":"brief","b":0,"text":"Only Congress may determine a lower federal court’s subject-matter jurisdiction.","cite":"138 S. Ct. at 17"}]},{"t":"case","label":"Hardt v. Reliance Standard Life Ins. Co.","cite":"560 U.S. 242","y":2010,"id":"2009/09-448","sc":1,"by":{"0":"35"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"by":{"0":"16, 17, 27","1":"16, 18, 19","2":"10"},"q":[{"src":"brief","b":0,"text":"promote the orderly progress of litigation.","cite":"562 U.S. at 435"},{"src":"brief","b":0,"text":"result[s] in the waste of judicial resources and may unfairly prejudice litigants.","cite":"562 U.S. at 434"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"seek to promote the orderly progress of litigation by requiring that the parties take certain procedural steps at certain specifed times.","cite":"562 U. S. 428, 435"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"many months of work on the part of the attorneys and the court.","cite":"562 U. S., at 434"}]},{"t":"case","label":"Hudson v. Parker","cite":"156 U.S. 277","y":1895,"id":"scdb/1894-090","sc":1,"by":{"0":"23","2":"7"}},{"t":"case","label":"ICC v. Jersey City","cite":"322 U.S. 503","y":1944,"id":"scdb/1943-065","sc":1,"by":{"0":"38"}},{"t":"case","label":"Indrawati v. U.S. Att’y Gen.","cite":"779 F.3d 1284","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/779/1284/","by":{"0":"45","1":"41"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"by":{"0":"5"}},{"t":"case","label":"INS v. Doherty","cite":"502 U.S. 314","y":1992,"id":"1991/90-925","sc":1,"by":{"0":"37"}},{"t":"case","label":"Jones v. Bock","cite":"549 U.S. 199","y":2007,"id":"2006/05-7058","sc":1,"by":{"0":"26, 28","1":"30","2":"7, 8"},"q":[{"src":"brief","b":0,"text":"failure to exhaust is an affirmative defense,","cite":"549 U.S. 199, 216"},{"src":"brief","b":0,"text":"complete the administrative review process in accordance with the applicable procedural rules.","cite":"549 U.S. at 218"},{"src":"brief","b":1,"text":"level of detail necessary * * * to comply with * * * the prison’s requirements.","cite":"549 U.S. 199, 218"}]},{"t":"case","label":"Kappos v. Hyatt","cite":"566 U.S. 431","y":2012,"id":"2011/10-1219","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"premature interruption of the administrative process.","cite":"566 U.S. 431, 439"}]},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"by":{"0":"28, 32","1":"14","2":"16"},"q":[{"src":"brief","b":0,"text":"Only Congress may determine a lower federal court’s subject-matter jurisdiction.","cite":"540 U.S. at 452"},{"src":"brief","b":1,"text":"determine [the] lower federal court[s’] subject-matter jurisdiction,","cite":"540 U.S. 443, 452"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"`merely prescrib[ing] the method by which the jurisdiction granted the courts by Congress is to be exercised.'","cite":"540 U. S., at 454"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"instruct the court on the limits of its discretion","cite":"540 U. S., at 456"}]},{"t":"case","label":"Korsunskiy v. Gonzalez","cite":"461 F.3d 847","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/461/847/","by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"a condition to success in court but not a limit on the set of cases that the judiciary has been assigned to resolve.","cite":"461 F.3d 847, 849"}]},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"by":{"0":"18, 37","1":"39, 40, 41","2":"9, 16, 21"},"q":[{"src":"brief","b":0,"text":"legislation regarding immigration, and particularly to questions concerning * * * jurisdiction.","cite":"558 U.S. 233, 251"},{"src":"brief","b":1,"text":"cancellation of removal, [8 U.S.C.] 1229b; permission for voluntary departure, [8 U.S.C.] 1229c; and adjustment of status, [8 U.S.C.] 1255.","cite":"558 U.S. 233, 246, 248"},{"src":"brief","b":2,"text":"From the Legislature’s silence on the discretion of the Attorney General (or his delegate, the Board) over reopening motions, we take it that Congress left the matter where it was pre-IIRIRA: The BIA has broad discretion, conferred by the Attorney General, ‘to grant or deny a motion to reopen.’","cite":"558 U.S. at 250"},{"src":"brief","b":2,"text":"precludes judicial review only when the statute itself specifies the discretionary character of the Attorney General’s authority,","cite":"558 U.S. at 244"}]},{"t":"case","label":"Kumar v. Garland","cite":"2022 WL 4364125","y":2022,"court":"5th Cir.","by":{"0":"34"}},{"t":"case","label":"Martinez-Guevara v. Garland","cite":"27 F.4th 353","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/27/353/","by":{"0":"34","1":"42"}},{"t":"case","label":"McNay v. Haitian Refugee Ctr., Inc.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"by":{"0":"18","1":"19"},"q":[{"src":"brief","b":0,"text":"well-settled presumption favoring interpretations of statutes that allow judicial review of administrative action.","cite":"498 U.S. 479, 496"},{"src":"brief","b":1,"text":"general federal-question jurisdiction under 28 U.S.C. § 1331","cite":"498 U.S. 479, 494"}]},{"t":"case","label":"McNeil v. United States","cite":"508 U.S. 106","y":1993,"id":"1992/92-6033","sc":1,"by":{"0":"47","1":"25","2":"8"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"by":{"0":"33"},"q":[{"src":"brief","b":0,"text":"the core of the prosecutorial function.","cite":"487 U.S. 654, 708"}]},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n of U.S., Inc. v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"by":{"0":"45"},"q":[{"src":"brief","b":0,"text":"a ‘rational connection between the facts found and the choice made.’","cite":"463 U.S. 29, 43"}]},{"t":"case","label":"Musacchio v. United States","cite":"577 U.S. 237","y":2016,"id":"2015/14-1095","sc":1,"by":{"0":"17"}},{"t":"case","label":"Nguhlefeh Njilefac v. Garland","cite":"992 F.3d 362","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/992/362/","by":{"0":"46"},"q":[{"src":"brief","b":0,"text":"unless the decision is ‘capricious, racially invidious, utterly without foundation in the evidence, or otherwise so irrational that it is arbitrary rather than the result of any perceptible rational approach.’","cite":"992 F.3d 362, 365"}]},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"by":{"0":"29"},"q":[{"src":"brief","b":0,"text":"this Court will first ascertain whether a construction of the statute is fairly possible by which the question may be avoided.","cite":"139 S. Ct. 954, 971"}]},{"t":"case","label":"Omari v. Holder","cite":"562 F.3d 314","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/562/314/","by":{"0":"12, 43, 44, 45","1":"34, 42"},"q":[{"src":"brief","b":0,"text":"itself results in a new issue.","cite":"562 F.3d at 320"}]},{"t":"case","label":"Ouedraogo v. Garland","cite":"2022 WL 2764733","y":2022,"court":"5th Cir.","by":{"0":"45"}},{"t":"case","label":"Owen Equip. & Erection Co. v. Kroger","cite":"437 U.S. 365","y":1978,"id":"1977/77-677","sc":1,"by":{"0":"29"}},{"t":"case","label":"Patchak v. Zinke","cite":"138 S. Ct. 897","y":2018,"id":"2017/16-498","sc":1,"by":{"0":"20, 21, 26","2":"3, 4, 6"},"q":[{"src":"brief","b":0,"text":"address[] ‘a court’s competence to adjudicate a particular category of cases.’","cite":"138 S. Ct. 897, 906"},{"src":"brief","b":2,"text":"a court’s competence to adjudicate a particular category of cases.","cite":"138 S. Ct. 897, 906"},{"src":"argument","who":"Mr. Hughes","text":"I think that's what this Court's Patchak case teaches, which is, if the -- the restriction goes to something substantive about the nature of the claims, some substantive category, that context suggests it is more likely the Court's speaking of jurisdiction."}]},{"t":"case","label":"Patel v. Garland","cite":"142 S. Ct. 1614","y":2022,"id":"2021/20-979","sc":1,"by":{"0":"28","1":"36, 39"},"q":[{"src":"brief","b":1,"text":"not a matter of right under any circumstances, but rather is in all cases a matter of grace.","cite":"142 S. Ct. at 1626"}]},{"t":"case","label":"Pena v. Garland","cite":"2022 WL 996574","y":2022,"court":"5th Cir.","by":{"0":"34"}},{"t":"case","label":"Pereida v. Wilkinson","cite":"141 S. Ct. 754","y":2021,"id":"2020/19-438","sc":1,"by":{"0":"33"},"q":[{"src":"brief","b":0,"text":"often are unrepresented, detained, or not fluent English speakers, [and] may not have the resources to offer more than their own testimony.","cite":"141 S. Ct. 754, 776"}]},{"t":"case","label":"Platte River Whooping Crane Critical Habitat Maint. Tr. v. FERC","cite":"876 F.2d 109","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/876/109/","by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"[p]arties seeking review of FERC orders must petition for rehearing of those orders and must themselves raise in that petition all of the objections urged on appeal.","cite":"876 F.2d 109, 113"}]},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"does not impose any legislative mandate to reopen upon the courts, but merely reflects and confirms the courts’ own inherent and discretionary power, ‘firmly established in English practice long before the foundation of our Republic.’","cite":"514 U.S. 211, 233-234"}]},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"by":{"0":"16, 17, 19, 20, 22, 23, 26","1":"16","2":"6, 7"},"q":[{"src":"brief","b":0,"text":"between jurisdictional prescriptions and claim-processing rules.","cite":"559 U.S. 154, 161"},{"src":"brief","b":0,"text":"statutory condition * * * is not automatically ‘a jurisdictional prerequisite to suit.’","cite":"559 U.S. at 166"}]},{"t":"case","label":"Romag Fasterns, Inc. v. Fossil, Inc.","cite":"140 S. Ct. 1492","y":2020,"id":"2019/18-1233","sc":1,"by":{"0":"40","2":"16"},"q":[{"src":"brief","b":0,"text":"read into [the] statute[] words that aren’t there.","cite":"140 S. Ct. 1492, 1495"}]},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"by":{"0":"35","1":"27, 38"},"q":[{"src":"brief","b":0,"text":"Statutory interpretation * * * begins with the text.","cite":"578 U.S. 632, 638"},{"src":"brief","b":1,"text":"capable of use to obtain some relief for the action complained of.","cite":"578 U.S. 632, 642"},{"src":"argument","who":"Mr. Hughes","text":"Blake, for example, the Court went through fairly extensive analysis that lower courts might need to undertake in order to determine whether or not a particular remedy in that case was available."},{"src":"argument","who":"Ms. Dubin","text":"And that's what the Court said in Ross versus Blake. So, in the exhaustion context in particular, what you want to know is whether the non-citizen has taken up all opportunities to present the agency with her arguments."},{"src":"argument","who":"Ms. Dubin","text":"So, under this Court's precedent in Ross versus Blake, it's simply not available to you to file a second motion to reconsider in that circumstance."}]},{"t":"case","label":"Saleh v. Barr","cite":"795 F. App’x 410","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/795/410/","by":{"0":"28"},"q":[{"src":"brief","b":0,"text":"[i]f Congress meant for [Section 1252(d)(1)]’s mandate to be jurisdictional, a court’s adjudicative power would turn on [the] agency’s rules and precedents for raising issues—rules and precedents that could change","cite":"795 F. App’x 410, 423"}]},{"t":"case","label":"Samsonyan v. Garland","cite":"2022 WL 4078577","y":2022,"court":"5th Cir.","by":{"0":"34"}},{"t":"case","label":"Santa Maria Ochoa v. Garland","cite":"2022 WL 4990263","y":2022,"court":"5th Cir.","by":{"0":"45, 46"},"q":[{"src":"brief","b":0,"text":"failed to present this new defect to the BIA in a motion to reconsider and so has failed to exhaust this issue.","cite":"2022 WL 4990263"}]},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"by":{"0":"26, 41","2":"2, 14"},"q":[{"src":"brief","b":0,"text":"it knew exactly how to do so—it could have simply borrowed from the statute next door.","cite":"138 S. Ct. 1348, 1355"},{"src":"brief","b":2,"text":"it could have simply borrowed from the statute next door.","cite":"138 S. Ct. 1348, 1355"},{"src":"brief","b":2,"text":"Congress’s choice to depart from the model of a closely related statute is a choice neither we nor the agency may disregard.","cite":"138 S. Ct. at 1355"}]},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"by":{"0":"15, 16, 17, 21, 30, 31","2":"3"},"q":[{"src":"brief","b":0,"text":"clearly state[s] that the rule is jurisdictional.","cite":"568 U.S. at 153"},{"src":"brief","b":2,"text":"requirement * * * does not become jurisdictional simply because it is placed in a section of a statute that also contains jurisdictional provisions.","cite":"568 U.S. 145, 155"}]},{"t":"case","label":"Sibbach v. Wilson & Co.","cite":"312 U.S. 1","y":1941,"id":"scdb/1940-046","sc":1,"by":{"0":"29"}},{"t":"case","label":"Sims v. Apfel","cite":"530 U.S. 103","y":2000,"id":"1999/98-9537","sc":1,"by":{"0":"30, 32","1":"passim","2":"12, 13, 15, 16, 17, 18"},"q":[{"src":"brief","b":0,"text":"an issue-exhaustion requirement is ‘an important corollary’ of any requirement of exhaustion of remedies.","cite":"530 U.S. 103, 107"},{"src":"brief","b":0,"text":"requirements of administrative issue exhaustion are * * * creatures of statute.","cite":"530 U.S. at 107"},{"src":"brief","b":2,"text":"requirements of administrative issue exhaustion are largely creatures of statute.","cite":"530 U.S. at 107"},{"src":"brief","b":2,"text":"based on ‘an analogy to the rule that appellate courts will not consider arguments not raised before trial courts’","cite":"530 U.S. at 109"},{"src":"argument","who":"Mr. Hughes","text":"And I think that's a -- a completely separate and independent concern with the government's position because, again, issue preservation, as this Court in -- in Carr and Sims and a series of cases has said, is a doctrine that is distinct from remedy exhaustion."}]},{"t":"case","label":"Steines v. Franklin Cnty.","cite":"81 U.S. 15","y":1871,"id":"scdb/1871-153","sc":1,"by":{"0":"38"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"by":{"0":"37, 41, 42, 43","1":"20, 21","2":"9, 10"},"q":[{"src":"brief","b":0,"text":"the statute is best understood as reflecting an intent on the part of Congress that deportation orders are to be reviewed in a timely fashion after issuance, irrespective of the later filing of a motion to reopen or reconsider.","cite":"514 U.S. at 394"},{"src":"brief","b":0,"text":"if he chooses, may also seek agency reconsideration of the order.","cite":"514 U.S. at 405"},{"src":"brief","b":2,"text":"must be construed with strict fidelity to their terms.","cite":"514 U.S. at 405"},{"src":"argument","who":"Mr. Hughes","text":"First, I don't think it's -- it's fair to read Stone as having said the exhaustion principle was jurisdictional. Certainly, there's no express holding that -- that would trigger a recodification provision -- or -- or -- or doctrine."},{"src":"argument","who":"Justice Sotomayor","text":"And Stone did not speak about exhaustion. Stone talked about jurisdiction with respect to time limits, correct?"}]},{"t":"case","label":"Twitchell v. Pennsylvania","cite":"74 U.S. 321","y":1868,"id":"scdb/1868-065","sc":1,"by":{"0":"36"}},{"t":"case","label":"Union Pac. R.R. Co. v. Brotherhood of Locomotive Eng’rs Gen. Comm. of Adjustment","cite":"558 U.S. 67","y":2009,"id":"2009/08-604","sc":1,"by":{"0":"27"}},{"t":"case","label":"United States v. ICC","cite":"396 U.S. 491","y":1970,"id":"1969/28","sc":1,"by":{"0":"38"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"by":{"0":"13, 17, 19, 27, 32","1":"14, 16, 17","2":"2, 5, 11"},"q":[{"src":"brief","b":0,"text":"imbue[] a procedural bar with jurisdictional consequences.","cite":"575 U.S. 402, 410"},{"src":"brief","b":0,"text":"deprive a court of authority to hear a case.","cite":"575 U.S. at 410"},{"src":"brief","b":2,"text":"speaks * * * to a court’s power.","cite":"575 U.S. at 410"},{"src":"brief","b":2,"text":"[J]urisdictional statutes speak about jurisdic- tion.","cite":"575 U.S. at 411 n.4"}]},{"t":"case","label":"United States v. Ruiz","cite":"536 U.S. 622","y":2002,"id":"2001/01-595","sc":1,"by":{"0":"23"}},{"t":"case","label":"Utility Air Reg. Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"by":{"0":"40","2":"17, 20"},"q":[{"src":"brief","b":2,"text":"rewrite clear statutory terms to suit its own sense of how the statute should operate.","cite":"573 U.S. 302, 328"},{"src":"brief","b":2,"text":"rewrite clear statutory terms to suit [the government’s] own sense of how the statute should operate.","cite":"573 U.S. at 328"}]},{"t":"case","label":"Ventura-De Caceres v. Garland","cite":"2022 WL 2168873","y":2022,"court":"5th Cir.","by":{"0":"46"}},{"t":"case","label":"Virginian Ry. Co. v. United States","cite":"272 U.S. 658","y":1926,"id":"scdb/1926-037","sc":1,"by":{"0":"36"}},{"t":"case","label":"Wachovia Bank, N.A. v. Schmidt","cite":"546 U.S. 303","y":2006,"id":"2005/04-1186","sc":1,"by":{"0":"20"}},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"by":{"0":"27","1":"17"}},{"t":"case","label":"Woelke & Romero Framing, Inc. v. NLRB","cite":"456 U.S. 645","y":1982,"id":"1981/80-1798","sc":1,"by":{"0":"30","1":"25","2":"8, 14"},"q":[{"src":"brief","b":0,"text":"[n]o objection that has not been urged before the Board . . . shall be considered by the court.","cite":"456 U.S. 645, 665"},{"src":"brief","b":2,"text":"[n]o objection that has not been urged before the Board … shall be considered by the court.","cite":"456 U.S. at 665"}]},{"t":"case","label":"Woodford v. Ngo","cite":"548 U.S. 81","y":2006,"id":"2005/05-416","sc":1,"by":{"0":"26, 28","1":"passim","2":"13, 14, 15"},"q":[{"src":"brief","b":0,"text":"that the PLRA exhaustion requirement is not jurisdictional.","cite":"548 U.S. 81, 101"},{"src":"brief","b":1,"text":"give[] an agency ‘an opportunity to correct its own mistakes’","cite":"548 U.S. 81, 89, 93"},{"src":"brief","b":1,"text":"mak[e] it clear that the PLRA exhaustion requirement is not jurisdictional.","cite":"548 U.S. 81, 101"},{"src":"argument","who":"Ms. Dubin","text":"And that's what this Court said in Woodford in interpreting the PLRA, which uses similar language. The second way is from available, I think, because the agency is not going to hear arguments you made before and -- and they've said that in In re OSG, which is agency precedent."}]},{"t":"case","label":"Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"by":{"0":"20"}},{"t":"usc","label":"5 U.S.C. § 7123","url":"https://www.law.cornell.edu/uscode/text/5/7123","subs":["(c)"],"by":{"0":"31"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(9)(B)(v)"],"by":{"0":"24"}},{"t":"usc","label":"15 U.S.C. § 77i","url":"https://www.law.cornell.edu/uscode/text/15/77i","subs":["(a)"],"by":{"0":"31"}},{"t":"usc","label":"16 U.S.C. § 825l","url":"https://www.law.cornell.edu/uscode/text/16/825l","subs":["(b)"],"by":{"0":"31, 40"}},{"t":"usc","label":"17 U.S.C. § 411","url":"https://www.law.cornell.edu/uscode/text/17/411","subs":["(a)"],"stext":{"head":"§411. Registration and civil infringement actions","paras":[[0,"(a) Except for an action brought for a violation of the rights of the author under section 106A(a), and subject to the provisions of subsection (b),1 no civil action for infringement of the copyright in any United States work shall be instituted until preregistration or registration of the copyright claim has been made in accordance with this title. In any case, however, where the deposit, application, and fee required for registration have been delivered to the Copyright Office in proper form and registration has been refused, the applicant is entitled to institute a civil action for infringement if notice thereof, with a copy of the complaint, is served on the Register of Copyrights. The Register may, at his or her option, become a party to the action with respect to the issue of registrability of the copyright claim by entering an appearance within sixty days after such service, but the Register's failure to become a party shall not deprive the court of jurisdiction to determine that issue."],[0,"(b)(1) A certificate of registration satisfies the requirements of this section and section 412, regardless of whether the certificate contains any inaccurate information, unless—"],[1,"(A) the inaccurate information was included on the application for copyright registration with knowledge that it was inaccurate; and"],[1,"(B) the inaccuracy of the information, if known, would have caused the Register of Copyrights to refuse registration."],[0,"(2) In any case in which inaccurate information described under paragraph (1) is alleged, the court shall request the Register of Copyrights to advise the court whether the inaccurate information, if known, would have caused the Register of Copyrights to refuse registration."],[0,"(3) Nothing in this subsection shall affect any rights, obligations, or requirements of a person related to information contained in a registration certificate, except for the institution of and remedies in infringement actions under this section and section 412."],[0,"(c) In the case of a work consisting of sounds, images, or both, the first fixation of which is made simultaneously with its transmission, the copyright owner may, either before or after such fixation takes place, institute an action for infringement under section 501, fully subject to the remedies provided by sections 502 through 505 and section 510, if, in accordance with requirements that the Register of Copyrights shall prescribe by regulation, the copyright owner—"],[1,"(1) serves notice upon the infringer, not less than 48 hours before such fixation, identifying the work and the specific time and source of its first transmission, and declaring an intention to secure copyright in the work; and"],[1,"(2) makes registration for the work, if required by subsection (a), within three months after its first transmission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/17/411?type=usc&year=mostrecent&link-type=html"},"by":{"0":"20","1":"17"}},{"t":"usc","label":"27 U.S.C. § 204","url":"https://www.law.cornell.edu/uscode/text/27/204","subs":["(h)"],"by":{"0":"31"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1","2":"20"}},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","subs":["(e)"],"stext":{"head":"§160. Prevention of unfair labor practices","paras":[[0,"(a) Powers of Board generally"],[0,"The Board is empowered, as hereinafter provided, to prevent any person from engaging in any unfair labor practice (listed in section 158 of this title) affecting commerce. This power shall not be affected by any other means of adjustment or prevention that has been or may be established by agreement, law, or otherwise: Provided, That the Board is empowered by agreement with any agency of any State or Territory to cede to such agency jurisdiction over any cases in any industry (other than mining, manufacturing, communications, and transportation except where predominantly local in character) even though such cases may involve labor disputes affecting commerce, unless the provision of the State or Territorial statute applicable to the determination of such cases by such agency is inconsistent with the corresponding provision of this subchapter or has received a construction inconsistent therewith."],[0,"(b) Complaint and notice of hearing; answer; court rules of evidence inapplicable"],[0,"Whenever it is charged that any person has engaged in or is engaging in any such unfair labor practice, the Board, or any agent or agency designated by the Board for such purposes, shall have power to issue and cause to be served upon such person a complaint stating the charges in that respect, and containing a notice of hearing before the Board or a member thereof, or before a designated agent or agency, at a place therein fixed, not less than five days after the serving of said complaint: Provided, That no complaint shall issue based upon any unfair labor practice occurring more than six months prior to the filing of the charge with the Board and the service of a copy thereof upon the person against whom such charge is made, unless the person aggrieved thereby was prevented from filing such charge by reason of service in the armed forces, in which event the six-month period shall be computed from the day of his discharge. Any such complaint may be amended by the member, agent, or agency conducting the hearing or the Board in its discretion at any time prior to the issuance of an order based thereon. The person so complained of shall have the right to file an answer to the original or amended complaint and to appear in person or otherwise and give testimony at the place and time fixed in the complaint. In the discretion of the member, agent, or agency conducting the hearing or the Board, any other person may be allowed to intervene in the said proceeding and to present testimony. Any such proceeding shall, so far as practicable, be conducted in accordance with the rules of evidence applicable in the district courts of the United States under the rules of civil procedure for the district courts of the United States, adopted by the Supreme Court of the United States pursuant to section 2072 of title 28."],[0,"(c) Reduction of testimony to writing; findings and orders of Board"],[0,"The testimony taken by such member, agent, or agency or the Board shall be reduced to writing and filed with the Board. Thereafter, in its discretion, the Board upon notice may take further testimony or hear argument. If upon the preponderance of the testimony taken the Board shall be of the opinion that any person named in the complaint has engaged in or is engaging in any such unfair labor practice, then the Board shall state its findings of fact and shall issue and cause to be served on such person an order requiring such person to cease and desist from such unfair labor practice, and to take such affirmative action including reinstatement of employees with or without back pay, as will effectuate the policies of this subchapter: Provided, That where an order directs reinstatement of an employee, back pay may be required of the employer or labor organization, as the case may be, responsible for the discrimination suffered by him: And provided further, That in determining whether a complaint shall issue alleging a violation of subsection (a)(1) or (a)(2) of section 158 of this title, and in deciding such cases, the same regulations and rules of decision shall apply irrespective of whether or not the labor organization affected is affiliated with a labor organization national or international in scope. Such order may further require such person to make reports from time to time showing the extent to which it has complied with the order. If upon the preponderance of the testimony taken the Board shall not be of the opinion that the person named in the complaint has engaged in or is engaging in any such unfair labor practice, then the Board shall state its findings of fact and shall issue an order dismissing the said complaint. No order of the Board shall require the reinstatement of any individual as an employee who has been suspended or discharged, or the payment to him of any back pay, if such individual was suspended or discharged for cause. In case the evidence is presented before a member of the Board, or before an administrative law judge or judges thereof, such member, or such judge or judges as the case may be, shall issue and cause to be served on the parties to the proceeding a proposed report, together with a recommended order, which shall be filed with the Board, and if no exceptions are filed within twenty days after service thereof upon such parties, or within such further period as the Board may authorize, such recommended order shall become the order of the Board and become effective as therein prescribed."],[0,"(d) Modification of findings or orders prior to filing record in court"],[0,"Until the record in a case shall have been filed in a court, as hereinafter provided, the Board may at any time upon reasonable notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any finding or order made or issued by it."],[0,"(e) Petition to court for enforcement of order; proceedings; review of judgment"],[0,"The Board shall have power to petition any court of appeals of the United States, or if all the courts of appeals to which application may be made are in vacation, any district court of the United States, within any circuit or district, respectively, wherein the unfair labor practice in question occurred or wherein such person resides or transacts business, for the enforcement of such order and for appropriate temporary relief or restraining order, and shall file in the court the record in the proceedings, as provided in section 2112 of title 28. Upon the filing of such petition, the court shall cause notice thereof to be served upon such person, and thereupon shall have jurisdiction of the proceeding and of the question determined therein, and shall have power to grant such temporary relief or restraining order as it deems just and proper, and to make and enter a decree enforcing, modifying and enforcing as so modified, or setting aside in whole or in part the order of the Board. No objection that has not been urged before the Board, its member, agent, or agency, shall be considered by the court, unless the failure or neglect to urge such objection shall be excused because of extraordinary circumstances. The findings of the Board with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall be conclusive. If either party shall apply to the court for leave to adduce additional evidence and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the hearing before the Board, its member, agent, or agency, the court may order such additional evidence to be taken before the Board, its member, agent, or agency, and to be made a part of the record. The Board may modify its findings as to the facts, or make new findings by reason of additional evidence so taken and filed, and it shall file such modified or new findings, which findings with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall be conclusive, and shall file its recommendations, if any, for the modification or setting aside of its original order. Upon the filing of the record with it the jurisdiction of the court shall be exclusive and its judgment and decree shall be final, except that the same shall be subject to review by the appropriate United States court of appeals if application was made to the district court as hereinabove provided, and by the Supreme Court of the United States upon writ of certiorari or certification as provided in section 1254 of title 28."],[0,"(f) Review of final order of Board on petition to court"],[0,"Any person aggrieved by a final order of the Board granting or denying in whole or in part the relief sought may obtain a review of such order in any United States court of appeals in the circuit wherein the unfair labor practice in question was alleged to have been engaged in or wherein such person resides or transacts business, or in the United States Court of Appeals for the District of Columbia, by filing in such a court a written petition praying that the order of the Board be modified or set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Board, and thereupon the aggrieved party shall file in the court the record in the proceeding, certified by the Board, as provided in section 2112 of title 28. Upon the filing of such petition, the court shall proceed in the same manner as in the case of an application by the Board under subsection (e), and shall have the same jurisdiction to grant to the Board such temporary relief or restraining order as it deems just and proper, and in like manner to make and enter a decree enforcing, modifying, and enforcing as so modified, or setting aside in whole or in part the order of the Board; the findings of the Board with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall in like manner be conclusive."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/160?type=usc&year=mostrecent&link-type=html"},"by":{"0":"30, 31","1":"25","2":"8, 14"}},{"t":"law","label":"Pub. L. No. 87-301","url":"https://www.govinfo.gov/link/statute/75/650","by":{"0":"6","1":"3","2":"11"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"5, 6, 24, 25","1":"4","2":"5"}},{"t":"law","label":"Pub. L. No. 109-13","url":"https://www.govinfo.gov/link/plaw/109/public/13","by":{"0":"25","1":"4"}},{"t":"reg","label":"8 C.F.R. § 1003.1","url":"https://www.ecfr.gov/current/title-8/section-1003.1","subs":["(d)(3)(iv)"],"by":{"0":"5, 13"},"q":[{"src":"brief","b":0,"text":"facts that are not reasonably subject to dispute.","cite":"8 C.F.R. § 1003.1(d)(3)(iv)"}]},{"t":"rule","label":"Fed. R. App. P. 3","url":"https://www.law.cornell.edu/rules/frap/rule_3","subs":["(a)(2)"],"by":{"0":"35","2":"20"},"q":[{"src":"brief","b":2,"text":"ground[s] * * * for * * * dismissing the appeal.","cite":"Fed. R. App. P. 3(a)(2)"}]},{"t":"rule","label":"Fed. R. App. P. 5","url":"https://www.law.cornell.edu/rules/frap/rule_5","by":{"0":"35"}},{"t":"rule","label":"Fed. R. Civ. P. 24","url":"https://www.law.cornell.edu/rules/frcp/rule_24","subs":["(a)","(b)"],"by":{"0":"38, 36, 36","2":"20"}},{"t":"case","label":"Asencio v. INS","cite":"37 F.3d 614","y":1994,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/37/614/","by":{"1":"21"}},{"t":"case","label":"Barron v. Ashcroft","cite":"358 F.3d 674","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/358/674/","by":{"1":"34"}},{"t":"case","label":"Barros v. Garland","cite":"31 F.4th 51","y":2022,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/31/51/","by":{"1":"42"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"by":{"1":"2"}},{"t":"case","label":"Cheng Fan Kwok v. INS","cite":"392 U.S. 206","y":1968,"id":"1967/638","sc":1,"by":{"1":"20"}},{"t":"case","label":"Dada v. Mukasey","cite":"554 U.S. 1","y":2008,"id":"2007/06-1181","sc":1,"by":{"1":"38"}},{"t":"case","label":"Day v. McDonough","cite":"547 U.S. 198","y":2006,"id":"2005/04-1324","sc":1,"by":{"1":"27","2":"12"}},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"by":{"1":"19"}},{"t":"case","label":"Elgin v. Department of the Treas.","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"by":{"1":"25"}},{"t":"case","label":"Etchu-Njang v. Gonzales","cite":"403 F.3d 577","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/403/577/","by":{"1":"34"}},{"t":"case","label":"Fernandez-Bernal v. Attorney Gen.","cite":"257 F.3d 1304","y":2001,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/257/1304/","by":{"1":"34"}},{"t":"case","label":"Foti v. INS","cite":"375 U.S. 217","y":1963,"id":"1963/28","sc":1,"by":{"1":"3"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"by":{"1":"25, 26"},"q":[{"src":"brief","b":1,"text":"the claims at issue ‘are of the type Congress intended to be reviewed within the statutory structure.’","cite":"561 U.S. 477, 489"}]},{"t":"case","label":"Gallegos v. Garland","cite":"25 F.4th 1087","y":2022,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/25/1087/","by":{"1":"41, 42"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"by":{"1":"15","2":"3, 6"}},{"t":"case","label":"INS v. Stevic","cite":"467 U.S. 407","y":1984,"id":"1983/82-973","sc":1,"by":{"1":"41"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"by":{"1":"19, 20","2":"5"},"q":[{"src":"brief","b":2,"text":"a ‘discretionary judgment’ by the Attorney General or a ‘decision’ that the Attorney General has made regarding * * * detention or release.","cite":"138 S. Ct. 830, 841"}]},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"by":{"1":"21","2":"10"}},{"t":"case","label":"Lockerty v. Phillips","cite":"319 U.S. 182","y":1943,"id":"scdb/1942-149","sc":1,"by":{"1":"14"}},{"t":"case","label":"Macauley v. Waterman S.S. Corp.","cite":"327 U.S. 540","y":1946,"id":"scdb/1945-065","sc":1,"by":{"1":"25"}},{"t":"case","label":"Margalli-Olvera v. INS","cite":"43 F.3d 345","y":1994,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/43/345/","by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"presumptively was aware of the longstanding judicial interpretation of the phrase and intended for it to retain its established meaning","cite":"43 F.3d 345, 350"}]},{"t":"case","label":"Massis v. Mukasey","cite":"549 F.3d 631","y":2008,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/549/631/","by":{"1":"34"}},{"t":"case","label":"Mata v. Lynch","cite":"576 U.S. 143","y":2015,"id":"2014/14-185","sc":1,"by":{"1":"38"}},{"t":"case","label":"McCarthy v. Madigan","cite":"503 U.S. 140","y":1992,"id":"1991/90-6861","sc":1,"by":{"1":"28"}},{"t":"case","label":"Meng Hua Wan v. Holder","cite":"776 F.3d 52","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/776/52/","by":{"1":"41, 42"}},{"t":"case","label":"Molina v. Holder","cite":"763 F.3d 1259","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/763/1259/","by":{"1":"34"}},{"t":"case","label":"Myers v. Bethlehem Shipbuilding Corp.","cite":"303 U.S. 41","y":1938,"id":"scdb/1937-127","sc":1,"by":{"1":"28"},"q":[{"src":"brief","b":1,"text":"until the prescribed administrative remedy has been exhausted.","cite":"303 U.S. 41, 50-51"}]},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"by":{"1":"4, 21","2":"10"},"q":[{"src":"argument","who":"Justice Kavanaugh","text":"And -- and in Nken, we repeated that post -- you know, post the -- the new act and post-Arbaugh, right?"}]},{"t":"case","label":"Northcross v. Board of Educ. of the Memphis City Sch.","cite":"412 U.S. 427","y":1973,"id":"1972/72-1164","sc":1,"by":{"1":"28"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"139 S. Ct. 710","y":2019,"id":"2018/17-1094","sc":1,"by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"be waived or forfeited by an opposing party,","cite":"139 S. Ct. 710, 714"}]},{"t":"case","label":"Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"by":{"1":"41"},"q":[{"src":"brief","b":1,"text":"practical considerations * * * do not justify departing from the statute’s clear text.","cite":"138 S. Ct. 2105, 2118"}]},{"t":"case","label":"Perkovic v. INS","cite":"33 F.3d 615","y":1994,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/33/615/","by":{"1":"21"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs., Inc.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"by":{"1":"16","2":"6"},"q":[{"src":"brief","b":1,"text":"‘order remanding a case to the State court from which it was removed is not reviewable on appeal or otherwise.’","cite":"551 U.S. 224, 229"}]},{"t":"case","label":"Ramani v. Ashcroft","cite":"378 F.3d 554","y":2004,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/378/554/","by":{"1":"34"}},{"t":"case","label":"Ravindran v. INS","cite":"976 F.2d 754","y":1992,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/976/754/","by":{"1":"21"}},{"t":"case","label":"Reno v. Catholic Soc. Servs., Inc.","cite":"509 U.S. 43","y":1993,"id":"1992/91-1826","sc":1,"by":{"1":"19"}},{"t":"case","label":"Rockwell Int’l Corp. v. United States","cite":"549 U.S. 457","y":2007,"id":"2006/05-1272","sc":1,"by":{"1":"12, 14, 23","2":"7"},"q":[{"src":"brief","b":1,"text":"[n]othing prevents Congress from defining the ‘category’ of excluded suits in any manner it wishes.","cite":"549 U.S. at 469"},{"src":"argument","who":"Ms. Dubin","text":"I think that the -- the Court said this in Rockwell, that Congress can define \"jurisdiction\" as it wishes, depending on what it decides is the requisite criteria."}]},{"t":"case","label":"Shaughnessy v. Pedreiro","cite":"349 U.S. 48","y":1955,"id":"scdb/1954-069","sc":1,"by":{"1":"3"}},{"t":"case","label":"Sidabutar v. Gonzales","cite":"503 F.3d 1116","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/503/1116/","by":{"1":"41, 42"}},{"t":"case","label":"Sousa v. INS","cite":"226 F.3d 28","y":2000,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/226/28/","by":{"1":"34"}},{"t":"case","label":"Townsend v. INS","cite":"799 F.2d 179","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/799/179/","by":{"1":"21"}},{"t":"case","label":"Thunder Basin Coal Co. v. Reich","cite":"510 U.S. 200","y":1994,"id":"1993/92-896","sc":1,"by":{"1":"25"}},{"t":"case","label":"United States v. Denedo","cite":"556 U.S. 904","y":2009,"id":"2008/08-267","sc":1,"by":{"1":"15","2":"6"},"q":[{"src":"argument","who":"Ms. Dubin","text":"In Gonzalez and Denedo, both of those turned on the lower court procedures, and that is how the jurisdiction bar worked in both of those cases."}]},{"t":"case","label":"United States v. L. A. Tucker Truck Lines, Inc.","cite":"344 U.S. 33","y":1952,"id":"scdb/1952-007","sc":1,"by":{"1":"29, 38","2":"15"}},{"t":"case","label":"United States v. Palomar-Santiago","cite":"141 S. Ct. 1615","y":2021,"id":"2020/20-437","sc":1,"by":{"1":"27","2":"12"},"q":[{"src":"brief","b":1,"text":"[w]hen Congress uses ‘mandatory language’ in an administrative exhaustion provision, ‘a court may not excuse a failure to exhaust,’","cite":"141 S. Ct. 1615, 1621"}]},{"t":"case","label":"Vargas v. INS","cite":"831 F.2d 906","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/831/906/","by":{"1":"21"}},{"t":"case","label":"Whitney Nat’l Bank in Jefferson Parish v. Bank of New Orleans & Trust Co.","cite":"379 U.S. 411","y":1965,"id":"1964/26","sc":1,"by":{"1":"26"}},{"t":"case","label":"Xie v. Ashcroft","cite":"359 F.3d 239","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/359/239/","by":{"1":"34"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"14"}},{"t":"usc","label":"28 U.S.C. § 2341","url":"https://www.law.cornell.edu/uscode/text/28/2341","by":{"1":"2"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"1":"3"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","by":{"1":"25"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)"],"by":{"1":"2, 2"}},{"t":"usc","label":"8 U.S.C. § 1105a","url":"https://www.law.cornell.edu/uscode/text/8/1105a","subs":["(1994)","(a)","(c)(1994)"],"stext":{"head":"§1105a. Employment authorization for battered spouses of certain nonimmigrants","paras":[[0,"(a) In general"],[0,"In the case of an alien spouse admitted under subparagraph (A), (E)(iii), (G), or (H) of section 1101(a)(15) of this title who is accompanying or following to join a principal alien admitted under subparagraph (A), (E)(iii), (G), or (H) of such section, respectively, the Secretary of Homeland Security may authorize the alien spouse to engage in employment in the United States and provide the spouse with an \"employment authorized\" endorsement or other appropriate work permit if the alien spouse demonstrates that during the marriage the alien spouse or a child of the alien spouse has been battered or has been the subject of extreme cruelty perpetrated by the spouse of the alien spouse. Requests for relief under this section shall be handled under the procedures that apply to aliens seeking relief under section 1154(a)(1)(A)(iii) of this title."],[0,"(b) Construction"],[0,"The grant of employment authorization pursuant to this section shall not confer upon the alien any other form of relief."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1105a?type=usc&year=mostrecent&link-type=html"},"by":{"1":"3, 4, 20, 3, 20, 3, 4, 21","2":"10"},"q":[{"src":"brief","b":1,"text":"shall not be reviewed in any court if the alien has not exhausted the administrative remedies available to him * * * or if he has departed from the United States after the issuance of the order.","cite":"8 U.S.C. 1105a(c)"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"order of deportation . . . shall not be reviewed by any court if the alien has not exhausted the administrative remedies available to him.","cite":"8 U. S. C. § 1105a(c)"}]},{"t":"usc","label":"8 U.S.C. § 1160","url":"https://www.law.cornell.edu/uscode/text/8/1160","subs":["(e)(1)"],"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"[t]here shall be no administrative or judicial review of a determination respecting an application for adjustment of status under this section except in ac- 5 The heading was included in Congress’s own enactment, not simply the version as codified at Section 1252(a)(2). See IIRIRA § 306(a)(2), 110 Stat. 3009-607. cordance with this subsection,","cite":"8 U.S.C. 1160(e)(1)"}]},{"t":"usc","label":"8 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/8/1226","subs":["(e)"],"by":{"1":"19, 20"},"q":[{"src":"brief","b":1,"text":"[n]o court may set aside any action or decision","cite":"8 U.S.C. 1226(e)"}]},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(a)(1)","(c)(5)","(c)(6)","(c)(6)(A)","(c)(6)(B)","(c)(6)(C)","(c)(7)","(c)(7)(A)","(c)(7)(B)","(c)(7)(C)"],"by":{"1":"7, 7, 7, 7, 7, 7, 7, 7, 7, 7, 7"},"q":[{"src":"brief","b":1,"text":"proceedings for deciding the inadmissibility or deportability of an alien,","cite":"8 U.S.C. 1229a(a)(1)"},{"src":"brief","b":1,"text":"shall inform the alien of the right to appeal","cite":"8 U.S.C. 1229a(c)(5)"}]},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(b)(3)","(b)(3)(A)","(b)(3)(C)"],"by":{"1":"7, 7, 10"},"q":[{"src":"brief","b":1,"text":"race, religion, nationality, membership in a particular social group, or political opinion.","cite":"8 U.S.C. 1231(b)(3)(A)"}]},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)","(a)(2)","(a)(2)(B)","(a)(5)","(b)(1)","(b)(4)","(b)(4)(A)","(b)(6)","(b)(9)","(d)","(d)(1)","(d)(2)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"by":{"1":"24, 24, 24, 24, 24, 24, 24, 24, 24, 24, 24, 24, 24"},"q":[{"src":"brief","b":1,"text":"[e]xcept as otherwise provided in this section,","cite":"8 U.S.C. 1252(b)(9)"},{"src":"brief","b":1,"text":"[a] court may review a final order of removal only if * * * the alien has exhausted all administrative remedies available to the alien as of right.","cite":"8 U.S.C. 1252(d)(1)"},{"src":"argument","who":"Mr. Hughes","text":"So, in the context of Section 1252 itself, we cite to provision (b)(2) in the briefs, where (b)(2) says, \"The court of appeals shall review the proceeding on typewritten briefs.\" That's mandatory."}]},{"t":"usc","label":"8 U.S.C. § 1255a","url":"https://www.law.cornell.edu/uscode/text/8/1255a","by":{"1":"24"}},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","subs":["(a)","(c)(2)"],"by":{"1":"24, 24, 24"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"1":"12"}},{"t":"usc","label":"10 U.S.C. § 867","url":"https://www.law.cornell.edu/uscode/text/10/867","subs":["(a)(2006)","(a)","(c)(2006)","(c)"],"stext":{"head":"§867. Art. 67. Review by the Court of Appeals for the Armed Forces","paras":[[0,"(a) The Court of Appeals for the Armed Forces shall review the record in—"],[1,"(1) all cases in which the sentence, as affirmed by a Court of Criminal Appeals, extends to death;"],[1,"(2) all cases reviewed by a Court of Criminal Appeals which the Judge Advocate General, after appropriate notification to the other Judge Advocates General and the Staff Judge Advocate to the Commandant of the Marine Corps, orders sent to the Court of Appeals for the Armed Forces for review; and"],[1,"(3) all cases reviewed by a Court of Criminal Appeals in which, upon petition of the accused and on good cause shown, the Court of Appeals for the Armed Forces has granted a review."],[0,"(b) The accused may petition the Court of Appeals for the Armed Forces for review of a decision of a Court of Criminal Appeals within 60 days from the earlier of—"],[1,"(1) the date on which the accused is notified of the decision of the Court of Criminal Appeals; or"],[1,"(2) the date on which a copy of the decision of the Court of Criminal Appeals, after being served on appellate counsel of record for the accused (if any), is deposited in the United States mails for delivery by first-class certified mail to the accused at an address provided by the accused or, if no such address has been provided by the accused, at the latest address listed for the accused in his official service record."],[0,"The Court of Appeals for the Armed Forces shall act upon such a petition promptly in accordance with the rules of the court."],[0,"(c)(1) In any case reviewed by it, the Court of Appeals for the Armed Forces may act only with respect to—"],[1,"(A) the findings and sentence set forth in the entry of judgment, as affirmed or set aside as incorrect in law by the Court of Criminal Appeals;"],[1,"(B) a decision, judgment, or order by a military judge, as affirmed or set aside as incorrect in law by the Court of Criminal Appeals; or"],[1,"(C) the findings set forth in the entry of judgment, as affirmed, dismissed, set aside, or modfied by the Court of Criminal Appeals as incorrect in fact under section 866(d)(1)(B) of this title (article 66(d)(1)(B))."],[0,"(2) In a case which the Judge Advocate General orders sent to the Court of Appeals for the Armed Forces, that action need be taken only with respect to the issues raised by him."],[0,"(3) In a case reviewed upon petition of the accused, that action need be taken only with respect to issues specified in the grant of review."],[0,"(4) The Court of Appeals for the Armed Forces shall take action only with respect to matters of law."],[0,"(d) If the Court of Appeals for the Armed Forces sets aside the findings and sentence, it may, except where the setting aside is based on lack of sufficient evidence in the record to support the findings, order a rehearing. If it sets aside the findings and sentence and does not order a rehearing, it shall order that the charges be dismissed."],[0,"(e) After it has acted on a case, the Court of Appeals for the Armed Forces may direct the Judge Advocate General to return the record to the Court of Criminal Appeals for further review in accordance with the decision of the court. Otherwise, unless there is to be further action by the President or the Secretary concerned, the Judge Advocate General shall instruct the convening authority to take action in accordance with that decision. If the court has ordered a rehearing, but the convening authority finds a rehearing impracticable, he may dismiss the charges. Notwithstanding the preceding sentence, if a case was referred to trial by a special trial counsel, a special trial counsel shall determine if a rehearing is impracticable and shall dismiss the charges if the special trial counsel so determines."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/867?type=usc&year=mostrecent&link-type=html"},"by":{"1":"16, 16, 15, 16, 15","2":"6"}},{"t":"usc","label":"28 U.S.C. § 1447","url":"https://www.law.cornell.edu/uscode/text/28/1447","subs":["(d)"],"by":{"1":"16"}},{"t":"usc","label":"28 U.S.C. § 2253","url":"https://www.law.cornell.edu/uscode/text/28/2253","subs":["(a)"],"by":{"1":"11, 15"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","by":{"1":"15"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(b)"],"by":{"1":"16"}},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(e)(4)(A)","(e)(4)(B)","(e)(4)"],"stext":{"head":"§3730. Civil actions for false claims","paras":[[0,"(a) Responsibilities of the Attorney General.—The Attorney General diligently shall investigate a violation under section 3729. If the Attorney General finds that a person has violated or is violating section 3729, the Attorney General may bring a civil action under this section against the person."],[0,"(b) Actions by Private Persons.—(1) A person may bring a civil action for a violation of section 3729 for the person and for the United States Government. The action shall be brought in the name of the Government. The action may be dismissed only if the court and the Attorney General give written consent to the dismissal and their reasons for consenting."],[0,"(2) A copy of the complaint and written disclosure of substantially all material evidence and information the person possesses shall be served on the Government pursuant to Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. The complaint shall be filed in camera, shall remain under seal for at least 60 days, and shall not be served on the defendant until the court so orders. The Government may elect to intervene and proceed with the action within 60 days after it receives both the complaint and the material evidence and information."],[0,"(3) The Government may, for good cause shown, move the court for extensions of the time during which the complaint remains under seal under paragraph (2). Any such motions may be supported by affidavits or other submissions in camera. The defendant shall not be required to respond to any complaint filed under this section until 20 days after the complaint is unsealed and served upon the defendant pursuant to Rule 4 of the Federal Rules of Civil Procedure."],[0,"(4) Before the expiration of the 60-day period or any extensions obtained under paragraph (3), the Government shall—"],[1,"(A) proceed with the action, in which case the action shall be conducted by the Government; or"],[1,"(B) notify the court that it declines to take over the action, in which case the person bringing the action shall have the right to conduct the action."],[0,"(5) When a person brings an action under this subsection, no person other than the Government may intervene or bring a related action based on the facts underlying the pending action."],[0,"(c) Rights of the Parties to Qui Tam Actions.—(1) If the Government proceeds with the action, it shall have the primary responsibility for prosecuting the action, and shall not be bound by an act of the person bringing the action. Such person shall have the right to continue as a party to the action, subject to the limitations set forth in paragraph (2)."],[0,"(2)(A) The Government may dismiss the action notwithstanding the objections of the person initiating the action if the person has been notified by the Government of the filing of the motion and the court has provided the person with an opportunity for a hearing on the motion."],[0,"(B) The Government may settle the action with the defendant notwithstanding the objections of the person initiating the action if the court determines, after a hearing, that the proposed settlement is fair, adequate, and reasonable under all the circumstances. Upon a showing of good cause, such hearing may be held in camera."],[0,"(C) Upon a showing by the Government that unrestricted participation during the course of the litigation by the person initiating the action would interfere with or unduly delay the Government's prosecution of the case, or would be repetitious, irrelevant, or for purposes of harassment, the court may, in its discretion, impose limitations on the person's participation, such as—"],[1,"(i) limiting the number of witnesses the person may call;"],[1,"(ii) limiting the length of the testimony of such witnesses;"],[1,"(iii) limiting the person's cross-examination of witnesses; or"],[1,"(iv) otherwise limiting the participation by the person in the litigation."],[0,"(D) Upon a showing by the defendant that unrestricted participation during the course of the litigation by the person initiating the action would be for purposes of harassment or would cause the defendant undue burden or unnecessary expense, the court may limit the participation by the person in the litigation."],[0,"(3) If the Government elects not to proceed with the action, the person who initiated the action shall have the right to conduct the action. If the Government so requests, it shall be served with copies of all pleadings filed in the action and shall be supplied with copies of all deposition transcripts (at the Government's expense). When a person proceeds with the action, the court, without limiting the status and rights of the person initiating the action, may nevertheless permit the Government to intervene at a later date upon a showing of good cause."],[0,"(4) Whether or not the Government proceeds with the action, upon a showing by the Government that certain actions of discovery by the person initiating the action would interfere with the Government's investigation or prosecution of a criminal or civil matter arising out of the same facts, the court may stay such discovery for a period of not more than 60 days. Such a showing shall be conducted in camera. The court may extend the 60-day period upon a further showing in camera that the Government has pursued the criminal or civil investigation or proceedings with reasonable diligence and any proposed discovery in the civil action will interfere with the ongoing criminal or civil investigation or proceedings."],[0,"(5) Notwithstanding subsection (b), the Government may elect to pursue its claim through any alternate remedy available to the Government, including any administrative proceeding to determine a civil money penalty. If any such alternate remedy is pursued in another proceeding, the person initiating the action shall have the same rights in such proceeding as such person would have had if the action had continued under this section. Any finding of fact or conclusion of law made in such other proceeding that has become final shall be conclusive on all parties to an action under this section. For purposes of the preceding sentence, a finding or conclusion is final if it has been finally determined on appeal to the appropriate court of the United States, if all time for filing such an appeal with respect to the finding or conclusion has expired, or if the finding or conclusion is not subject to judicial review."],[0,"(d) Award to Qui Tam Plaintiff.—(1) If the Government proceeds with an action brought by a person under subsection (b), such person shall, subject to the second sentence of this paragraph, receive at least 15 percent but not more than 25 percent of the proceeds of the action or settlement of the claim, depending upon the extent to which the person substantially contributed to the prosecution of the action. Where the action is one which the court finds to be based primarily on disclosures of specific information (other than information provided by the person bringing the action) relating to allegations or transactions in a criminal, civil, or administrative hearing, in a congressional, administrative, or Government 2 Accounting Office report, hearing, audit, or investigation, or from the news media, the court may award such sums as it considers appropriate, but in no case more than 10 percent of the proceeds, taking into account the significance of the information and the role of the person bringing the action in advancing the case to litigation. Any payment to a person under the first or second sentence of this paragraph shall be made from the proceeds. Any such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(2) If the Government does not proceed with an action under this section, the person bringing the action or settling the claim shall receive an amount which the court decides is reasonable for collecting the civil penalty and damages. The amount shall be not less than 25 percent and not more than 30 percent of the proceeds of the action or settlement and shall be paid out of such proceeds. Such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(3) Whether or not the Government proceeds with the action, if the court finds that the action was brought by a person who planned and initiated the violation of section 3729 upon which the action was brought, then the court may, to the extent the court considers appropriate, reduce the share of the proceeds of the action which the person would otherwise receive under paragraph (1) or (2) of this subsection, taking into account the role of that person in advancing the case to litigation and any relevant circumstances pertaining to the violation. If the person bringing the action is convicted of criminal conduct arising from his or her role in the violation of section 3729, that person shall be dismissed from the civil action and shall not receive any share of the proceeds of the action. Such dismissal shall not prejudice the right of the United States to continue the action, represented by the Department of Justice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3730?type=usc&year=mostrecent&link-type=html"},"by":{"1":"23, 23","2":"7"},"q":[{"src":"brief","b":2,"text":"clear and explicit * * * jurisdictional nature.","cite":"31 U.S.C. § 3730(e)(4)"}]},{"t":"usc","label":"38 U.S.C. § 7266","url":"https://www.law.cornell.edu/uscode/text/38/7266","subs":["(a)(2006)"],"by":{"1":"16"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(g)"],"by":{"1":"35"}},{"t":"reg","label":"20 C.F.R. § 802.211","url":"https://www.ecfr.gov/current/title-20/section-802.211","subs":["(a)"],"by":{"1":"31"}},{"t":"case","label":"Abdelqadar v. Gonzales","cite":"413 F.3d 668","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/413/668/","by":{"2":"6"}},{"t":"case","label":"Boudaguian v. Ashcroft","cite":"376 F.3d 825","y":2004,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/376/825/","by":{"2":"22"}},{"t":"case","label":"Carlyle Towers Condo. Ass’n, Inc. v. FDIC","cite":"170 F.3d 301","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/170/301/","by":{"2":"16"}},{"t":"case","label":"Copen v. United States","cite":"3 F.4th 875","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/3/875/","by":{"2":"8"}},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"by":{"2":"17"}},{"t":"case","label":"NLRB v. SW General, Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"by":{"2":"13"}},{"t":"case","label":"OOGC Am., LLC v. Chesapeake Exploration, LLC","cite":"975 F.3d 449","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/975/449/","by":{"2":"22"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"by":{"2":"13"},"q":[{"src":"brief","b":2,"text":"was a shorthand way of referring to all [forms of exhaustion]. Not because Congress is too unpoetic to use synecdoche, but because that literary device is incompatible with the need for precision in legislative drafting.","cite":"525 U.S. 471, 482"}]},{"t":"case","label":"United States v. Saladino","cite":"7 F.4th 120","y":2021,"court":"2d. Cir.","url":"https://www.courtlistener.com/c/F.4th/7/120/","by":{"2":"7"}},{"t":"case","label":"United States v. Sineneng-Smith","cite":"140 S. Ct. 1575","y":2020,"id":"2019/19-67","sc":1,"by":{"2":"11"},"q":[{"src":"brief","b":2,"text":"[t]hey ‘do not, or should not, sally forth each day looking for wrongs to right.’","cite":"140 S. Ct. 1575, 1579"},{"src":"argument","who":"Mr. Hughes","text":"And we point the Court to the Sineneng-Smith decision, where this Court said pretty clearly that the lower courts \"should not sally forth each day looking for wrong\" -- \"wrongs to right.\" You know, we're talking about the government here."}]},{"t":"case","label":"Zhong v. U.S. Dep’t of Justice","cite":"480 F.3d 104","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/480/104/","by":{"2":"18"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(c)(1)(A)"],"by":{"2":"7"}},{"t":"usc","label":"26 U.S.C. § 6330","url":"https://www.law.cornell.edu/uscode/text/26/6330","subs":["(d)(1)"],"by":{"2":"5"},"q":[{"src":"brief","b":2,"text":"may, within 30 days of a determination * * *, petition the Tax Court for review of such determination (and the Tax Court shall have jurisdiction with respect to such matter).","cite":"26 U.S.C. § 6330(d)(1)"}]},{"t":"reg","label":"8 C.F.R. § 1003.2","url":"https://www.ecfr.gov/current/title-8/section-1003.2","subs":["(a)"],"by":{"2":"19, 21"},"q":[{"src":"brief","b":2,"text":"[t]he decision to grant or deny a motion to * * * reconsider is within the discretion of the Board","cite":"8 C.F.R. § 1003.2(a)"}]}]};